let inputPrompt = $input.first().json.output;

// 1. Remove line breaks
let cleanPrompt = inputPrompt.split(/\r?\n/).join(" ");

// 2. Remove Markdown (** and * bullets)
cleanPrompt = cleanPrompt.replace(/\*\*/g, "").replace(/\*/g, "");

// 3. Replace double quotes with single quotes
cleanPrompt = cleanPrompt.replace(/"/g, "'");

// 4. Build n8n-compatible return
return [
  {
    json: {
      prompt: cleanPrompt
    }
  }
];

// Convert fal.ai JSON response (data URI) into a downloadable image file
const items = $input.all();
const results = [];

for (const item of items) {
  // works whether "Full Response" is on or off
  const body = item.json.images ? item.json : (item.json.body || {});
  const images = body.images || [];
  const dataUri = images[0] && images[0].url ? images[0].url : '';

  if (dataUri.indexOf('data:') !== 0) {
    throw new Error('No image found in response: ' + JSON.stringify(item.json).slice(0, 200));
  }

  const mimeType = (dataUri.match(/^data:([^;]+);/) || [null, 'image/jpeg'])[1];
  const ext = mimeType === 'image/png' ? 'png' : 'jpg';
  const buffer = Buffer.from(dataUri.substring(dataUri.indexOf(',') + 1), 'base64');

  results.push({
    json: { fileName: 'moodboard.' + ext, mimeType: mimeType, sizeBytes: buffer.length },
    binary: {
      data: await this.helpers.prepareBinaryData(buffer, 'moodboard.' + ext, mimeType)
    }
  });
}

return results;
